| fork variant | returns when | effect here |
| --- | --- | --- |
| `join` | all branches done | correct |
| `join_any` | first branch done | datapath races B's config |
| `join_none` | immediately | datapath starts before any config |

### Code
```systemverilog
class block_config_seq extends uvm_sequence #(reg_seq_item);
  `uvm_object_utils(block_config_seq)

  bit [31:0] base_addr;

  function new(string name = "block_config_seq"); super.new(name); endfunction

  task body();
    for (int i = 0; i < 5; i++) begin
      reg_seq_item req = reg_seq_item::type_id::create($sformatf("req%0d", i));
      start_item(req);
      if (!req.randomize() with {
            addr       == base_addr + i*4;
            data       == 32'h1000 + i;
            read_write == 0;
          })
        `uvm_fatal(get_full_name(), "randomize failed")
      finish_item(req);
    end
  endtask
endclass

class top_vseq extends uvm_sequence;
  `uvm_object_utils(top_vseq)
  `uvm_declare_p_sequencer(virtual_sequencer)

  function new(string name = "top_vseq"); super.new(name); endfunction

  task body();
    block_config_seq a  = block_config_seq::type_id::create("a");
    block_config_seq b  = block_config_seq::type_id::create("b");
    datapath_seq     dp = datapath_seq::type_id::create("dp");

    a.base_addr = 32'h1000;
    b.base_addr = 32'h2000;

    fork
      a.start(p_sequencer.seqr_a);
      b.start(p_sequencer.seqr_b);
    join                               // both configs complete

    dp.start(p_sequencer.seqr_dp);
  endtask
endclass
```

### Corner cases & pitfalls
